"use client";

import Link from "next/link";
import Image from "next/image";
import { useMemo, useState, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import { ChevronRight, FileUp, Pencil, Plus, Search, Star, Trash2, X } from "lucide-react";
import { notifyAdmin } from "@/components/admin/admin-toast";

type Row = Record<string, unknown>;
type Product = Row & { id:string;slug:string;name:string;category_slug:string;images:string[];price_cents:number;sale_price_cents:number|null;stock_quantity:number;is_published:boolean;is_featured:boolean;featured_rank:number;product_variants?:Row[];variants?:Row[] };
type FeaturedProduct = Pick<Product,"id"|"name"|"is_featured"|"featured_rank"> & Partial<Product>;
type Variant = { id?:string;sku:string;name:string;options:Record<string,string>;priceAdjustmentCents:number;stockQuantity:number;isActive:boolean;sortOrder:number };
const money=(cents:number,currency="USD")=>new Intl.NumberFormat(undefined,{style:"currency",currency,maximumFractionDigits:2}).format((Number(cents)||0)/100);
const date=(v:unknown)=>v?new Date(String(v)).toLocaleDateString(undefined,{year:"numeric",month:"short",day:"numeric"}):"—";
async function requestJson(url:string, init?:RequestInit){const response=await fetch(url,{...init,headers:{"content-type":"application/json",...init?.headers}});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Request could not be completed.");return body;}
function Status({value}:{value:unknown}){const text=String(value??"unknown");const tone=["paid","delivered","active","published","succeeded"].includes(text)?"good":["failed","cancelled","refunded","inactive"].includes(text)?"bad":["pending","processing","unfulfilled","unpaid"].includes(text)?"warn":"";return <span className={`admin-badge ${tone}`}>{text.replaceAll("_"," ")}</span>;}
function Heading({eyebrow,title,detail,action}:{eyebrow:string;title:string;detail:string;action?:React.ReactNode}){return <div className="admin-heading-row"><div><div className="admin-eyebrow">{eyebrow}</div><h1>{title}</h1><p>{detail}</p></div>{action&&<div className="admin-actions">{action}</div>}</div>;}
function Modal({title,onClose,children}:{title:string;onClose:()=>void;children:React.ReactNode}){return <div className="admin-modal-backdrop" role="presentation" onMouseDown={(event)=>event.target===event.currentTarget&&onClose()}><section className="admin-modal" role="dialog" aria-modal="true" aria-label={title}><header className="admin-modal-head"><h2>{title}</h2><button className="admin-icon-button" aria-label="Close dialog" onClick={onClose}><X size={15}/></button></header>{children}</section></div>;}
function ErrorLine({error}:{error:string}){return error?<p className="admin-inline-error" role="alert">{error}</p>:null;}

export function ProductTable({initial}:{initial:Product[]}){
  const router=useRouter();const [query,setQuery]=useState("");const [category,setCategory]=useState("all");const [visibility,setVisibility]=useState("all");const [busy,setBusy]=useState("");const [error,setError]=useState("");
  const products=useMemo(()=>initial.filter(p=>`${p.name} ${p.slug} ${p.category_slug}`.toLowerCase().includes(query.toLowerCase())&&(category==="all"||p.category_slug===category)&&(visibility==="all"||(visibility==="published"?p.is_published:visibility==="draft"?!p.is_published:Number(p.stock_quantity)<=4))),[initial,query,category,visibility]);
  async function toggleFeature(product:Product){setBusy(product.id);setError("");try{await requestJson("/api/admin/content/featured",{method:"PATCH",body:JSON.stringify({id:product.id,isFeatured:!product.is_featured,featuredRank:product.featured_rank||999})});notifyAdmin(product.is_featured?"Product removed from featured surfaces.":"Product featured.");router.refresh();}catch(e){setError(e instanceof Error?e.message:"Could not update feature status.");}finally{setBusy("");}}
  async function remove(product:Product){if(!window.confirm(`Delete ${product.name}? This cannot be undone.`))return;setBusy(product.id);try{await requestJson(`/api/admin/products/${product.id}`,{method:"DELETE"});notifyAdmin("Product deleted.");router.refresh();}catch(e){setError(e instanceof Error?e.message:"Delete failed.");}finally{setBusy("");}}
  return <><Heading eyebrow="CATALOG / PRODUCTS" title="Product index" detail={`${initial.length} database records · manage catalog, pricing, variants and media`} action={<Link className="admin-button" href="/admin/products/new"><Plus size={14}/> New product</Link>}/><div className="admin-toolbar"><label className="admin-field admin-search" style={{display:"flex",alignItems:"center",gap:8}}><Search size={14}/><input aria-label="Search products" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name, slug, category" style={{border:0,outline:0,background:"transparent",color:"inherit",width:"100%"}}/></label><select className="admin-field admin-select" aria-label="Filter product category" value={category} onChange={e=>setCategory(e.target.value)}><option value="all">All categories</option>{["objects","audio","footwear","living","accessories"].map(value=><option key={value}>{value}</option>)}</select><select className="admin-field admin-select" aria-label="Filter product status" value={visibility} onChange={e=>setVisibility(e.target.value)}><option value="all">All status</option><option value="published">Published</option><option value="draft">Draft</option><option value="low-stock">Low stock (≤ 4)</option></select><span className="admin-muted">{products.length} shown</span></div><ErrorLine error={error}/><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th>Featured</th><th>Actions</th></tr></thead><tbody>{products.map(product=><tr key={product.id}><td><div className="admin-product-cell">{product.images?.[0]?<Image className="admin-thumb" src={product.images[0]} alt="" width={38} height={42} sizes="38px"/>:<div className="admin-thumb"/>}<div><b>{product.name}</b><span>/{product.slug}</span></div></div></td><td>{product.category_slug}</td><td>{money(product.sale_price_cents??product.price_cents)}</td><td>{product.stock_quantity}</td><td><Status value={product.is_published?"published":"draft"}/></td><td><button title={product.is_featured?"Remove from featured":"Feature product"} aria-label={`${product.is_featured?"Unfeature":"Feature"} ${product.name}`} className="admin-icon-button" disabled={busy===product.id} onClick={()=>toggleFeature(product)}><Star size={14} fill={product.is_featured?"#c3a77d":"none"} color={product.is_featured?"#c3a77d":"currentColor"}/></button></td><td><div className="admin-actions"><Link className="admin-button admin-button-quiet admin-button-small" href={`/admin/products/${product.id}`}><Pencil size={12}/> Edit</Link><button className="admin-button admin-button-danger admin-button-small" disabled={busy===product.id} onClick={()=>remove(product)} aria-label={`Delete ${product.name}`}><Trash2 size={12}/></button></div></td></tr>)}</tbody></table>{!products.length&&<div className="admin-empty"><strong>No matching products</strong>Try another search, or create a catalog record.</div>}</div></>;
}

function parseLines(value:string){return value.split(",").map(x=>x.trim()).filter(Boolean);}
function mapVariants(source:unknown):Variant[]{if(!Array.isArray(source))return[];return source.map((v:Row)=>({id:typeof v.id==="string"?v.id:undefined,sku:String(v.sku??""),name:String(v.name??""),options:(v.options??{}) as Record<string,string>,priceAdjustmentCents:Number(v.priceAdjustmentCents??v.price_adjustment_cents??0),stockQuantity:Number(v.stockQuantity??v.stock_quantity??0),isActive:Boolean(v.isActive??v.is_active??true),sortOrder:Number(v.sortOrder??v.sort_order??0)}));}
function formForProduct(product?:Product){return {slug:String(product?.slug??""),name:String(product?.name??""),description:String(product?.description??""),story:String(product?.story??""),categorySlug:String(product?.category_slug??"objects"),images:(product?.images??[]).join("\n"),imageAlt:String(product?.image_alt??""),materials:(product?.materials as string[]??[]).join(", "),colors:JSON.stringify(product?.color_swatches??[],null,2),price:String((Number(product?.price_cents??0)/100)||""),salePrice:product?.sale_price_cents==null?"":String(Number(product.sale_price_cents)/100),stock:String(product?.stock_quantity??0),collectionSlug:String(product?.collection_slug??"edition-001"),collectionName:String(product?.collection_name??"Edition 001 / The first signal"),published:Boolean(product?.is_published),featured:Boolean(product?.is_featured),rank:String(product?.featured_rank??999),modelUrl:String(product?.model_url??""),variants:JSON.stringify(mapVariants(product?.product_variants??product?.variants),null,2)};}

export function ProductEditor({product}:{product?:Product}){
  const router=useRouter();const [form,setForm]=useState(()=>formForProduct(product));const [error,setError]=useState("");const [busy,setBusy]=useState(false);const [uploading,setUploading]=useState(false);
  const change=(key:keyof typeof form,value:string|boolean)=>setForm(prev=>({...prev,[key]:value}));
  async function upload(file:File,kind:"image"|"model"){setUploading(true);setError("");try{const payload=new FormData();payload.set("file",file);payload.set("kind",kind);const response=await fetch("/api/admin/products/media",{method:"POST",body:payload});const data=await response.json();if(!response.ok)throw new Error(data.error||"Upload failed.");if(kind==="image")change("images",[...parseLines(form.images),data.url].join("\n"));else change("modelUrl",data.url);}catch(e){setError(e instanceof Error?e.message:"Upload failed.");}finally{setUploading(false);}}
  async function submit(event:FormEvent){event.preventDefault();setBusy(true);setError("");try{const colors=JSON.parse(form.colors);const variants=JSON.parse(form.variants);const cents=(value:string)=>Math.round(Number(value||0)*100);const payload={slug:form.slug,name:form.name,description:form.description,story:form.story,categorySlug:form.categorySlug,images:parseLines(form.images),imageAlt:form.imageAlt,materials:parseLines(form.materials),colors,priceCents:cents(form.price),salePriceCents:form.salePrice?cents(form.salePrice):null,stockQuantity:Number(form.stock),collectionSlug:form.collectionSlug,collectionName:form.collectionName,isPublished:form.published,isFeatured:form.featured,featuredRank:Number(form.rank),modelUrl:form.modelUrl||null,variants};await requestJson(product?`/api/admin/products/${product.id}`:"/api/admin/products",{method:product?"PATCH":"POST",body:JSON.stringify(payload)});notifyAdmin(product?"Product changes saved.":"Product created.");router.push("/admin/products");router.refresh();}catch(e){setError(e instanceof Error?e.message:"Product could not be saved. Check JSON fields and required values.");}finally{setBusy(false);}}
  return <><Heading eyebrow={product?"CATALOG / EDIT RECORD":"CATALOG / NEW RECORD"} title={product?product.name:"Create a product"} detail="Product data, media, stock and variants are stored in the VANTA catalog." action={<Link href="/admin/products" className="admin-button admin-button-quiet">Back to products</Link>}/><form onSubmit={submit} className="admin-panel admin-panel-pad"><div className="admin-form-grid">
    <Field label="Product name"><input className="admin-field" value={form.name} onChange={e=>change("name",e.target.value)} required maxLength={160}/></Field><Field label="URL slug"><input className="admin-field" value={form.slug} onChange={e=>change("slug",e.target.value)} required pattern="[a-z0-9]+(?:-[a-z0-9]+)*"/></Field>
    <Field label="Category"><select className="admin-field admin-select" value={form.categorySlug} onChange={e=>change("categorySlug",e.target.value)}>{["objects","audio","footwear","living","accessories"].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Collection slug"><input className="admin-field" value={form.collectionSlug} onChange={e=>change("collectionSlug",e.target.value)} required/></Field>
    <Field label="Collection name"><input className="admin-field" value={form.collectionName} onChange={e=>change("collectionName",e.target.value)} required/></Field><Field label="Price (USD)"><input className="admin-field" type="number" min="0" step="0.01" value={form.price} onChange={e=>change("price",e.target.value)} required/></Field>
    <Field label="Sale price (USD)"><input className="admin-field" type="number" min="0" step="0.01" value={form.salePrice} onChange={e=>change("salePrice",e.target.value)}/></Field><Field label="Base inventory"><input className="admin-field" type="number" min="0" step="1" value={form.stock} onChange={e=>change("stock",e.target.value)} required/></Field>
    <Field label="Description" full><textarea className="admin-textarea" value={form.description} onChange={e=>change("description",e.target.value)} required maxLength={2000}/></Field><Field label="Product story" full><textarea className="admin-textarea" value={form.story} onChange={e=>change("story",e.target.value)}/></Field>
    <Field label="Image URLs · one per line" full><textarea className="admin-textarea" value={form.images} onChange={e=>change("images",e.target.value)} placeholder="https://… or /images/…" required/><label className="admin-button admin-button-quiet admin-button-small" style={{width:"max-content",marginTop:7}}><FileUp size={12}/> {uploading?"Uploading…":"Upload product image"}<input hidden type="file" accept="image/jpeg,image/png,image/webp,image/avif" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0],"image")}/></label></Field>
    <Field label="Image alt text"><input className="admin-field" value={form.imageAlt} onChange={e=>change("imageAlt",e.target.value)} required maxLength={300}/></Field><Field label="Materials · comma separated"><input className="admin-field" value={form.materials} onChange={e=>change("materials",e.target.value)}/></Field>
    <Field label="Colors · JSON array of { name, hex }" full><textarea className="admin-textarea" value={form.colors} onChange={e=>change("colors",e.target.value)} placeholder='[{"name":"Stone","hex":"#b5ab9c"}]'/></Field>
    <Field label="3D model URL"><input className="admin-field" value={form.modelUrl} onChange={e=>change("modelUrl",e.target.value)} placeholder="Optional GLB/GLTF URL"/><label className="admin-button admin-button-quiet admin-button-small" style={{width:"max-content",marginTop:7}}><FileUp size={12}/> Upload 3D model<input hidden type="file" accept=".glb,.gltf,model/gltf-binary,model/gltf+json" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0],"model")}/></label></Field><Field label="Featured rank"><input className="admin-field" type="number" min="1" value={form.rank} onChange={e=>change("rank",e.target.value)}/></Field>
    <Field label="Variants · JSON array" full><textarea className="admin-textarea" style={{minHeight:145,fontFamily:"var(--font-mono)"}} value={form.variants} onChange={e=>change("variants",e.target.value)} placeholder='[{"sku":"SKU-01","name":"One size","options":{"size":"One size"},"priceAdjustmentCents":0,"stockQuantity":4,"isActive":true,"sortOrder":0}]'/><small className="admin-muted">Variant fields: sku, name, options, priceAdjustmentCents, stockQuantity, isActive, sortOrder. Existing IDs are retained while editing.</small></Field>
    <div className="admin-form-field"><span>VISIBILITY</span><label className="admin-check"><input type="checkbox" checked={form.published} onChange={e=>change("published",e.target.checked)}/> Published in storefront</label></div><div className="admin-form-field"><span>FEATURED</span><label className="admin-check"><input type="checkbox" checked={form.featured} onChange={e=>change("featured",e.target.checked)}/> Feature on curated surfaces</label></div>
  </div><ErrorLine error={error}/><div className="admin-modal-foot"><button type="button" className="admin-button admin-button-quiet" onClick={()=>router.push("/admin/products")}>Cancel</button><button disabled={busy||uploading} className="admin-button" type="submit">{busy?"Saving…":product?"Save product":"Create product"}</button></div></form></>;
}
function Field({label,children,full}:{label:string;children:React.ReactNode;full?:boolean}){return <label className={`admin-form-field ${full?"full":""}`}><span>{label}</span>{children}</label>;}

export function InventoryManager({initial}:{initial:{products:Row[];variants:Row[];movements:Row[]}}){
  const router=useRouter();const [productId,setProductId]=useState("");const [variantId,setVariantId]=useState("");const [delta,setDelta]=useState("");const [reason,setReason]=useState("");const [reference,setReference]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);
  const productVariants=initial.variants.filter(v=>v.product_id===productId);const selectedProduct=initial.products.find(v=>v.id===productId);
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{await requestJson("/api/admin/inventory/adjust",{method:"POST",body:JSON.stringify({productId,variantId:variantId||null,delta:Number(delta),reason,reference})});notifyAdmin("Inventory movement recorded.");setDelta("");setReason("");setReference("");router.refresh();}catch(x){setError(x instanceof Error?x.message:"Stock adjustment failed.");}finally{setBusy(false);}}
  return <><Heading eyebrow="COMMERCE / INVENTORY" title="Stock ledger" detail="Current product and variant stock with a recorded adjustment history."/><div className="admin-grid admin-overview-grid"><section><h2 className="admin-section-title">Current stock <small>{initial.products.length} products</small></h2><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Product / SKU</th><th>Variant</th><th>Available</th><th>Catalog</th></tr></thead><tbody>{initial.products.map(p=>{const variants=initial.variants.filter(v=>v.product_id===p.id);return variants.length?variants.map(v=><tr key={String(v.id)}><td><div className="admin-product-cell"><div><b>{String(p.name)}</b><span>{String(v.sku)}</span></div></div></td><td>{String(v.name)}</td><td><Status value={Number(v.stock_quantity)<=4?"low stock":"available"}/><span style={{marginLeft:8}}>{String(v.stock_quantity)}</span></td><td>{Boolean(p.is_published)?"Published":"Draft"}</td></tr>):<tr key={String(p.id)}><td><div className="admin-product-cell"><div><b>{String(p.name)}</b><span>{String(p.slug)}</span></div></div></td><td>Base stock</td><td><Status value={Number(p.stock_quantity)<=4?"low stock":"available"}/><span style={{marginLeft:8}}>{String(p.stock_quantity)}</span></td><td>{Boolean(p.is_published)?"Published":"Draft"}</td></tr>;})}</tbody></table></div></section><aside><h2 className="admin-section-title">Adjust stock <small>ADMIN LEDGER</small></h2><form className="admin-panel admin-panel-pad" onSubmit={submit}><div className="admin-form-grid"><Field label="Product"><select className="admin-field admin-select" required value={productId} onChange={e=>{setProductId(e.target.value);setVariantId("")}}><option value="">Select product</option>{initial.products.map(p=><option key={String(p.id)} value={String(p.id)}>{String(p.name)}</option>)}</select></Field><Field label="Variant"><select className="admin-field admin-select" value={variantId} onChange={e=>setVariantId(e.target.value)}><option value="">{productVariants.length?"Base product stock":"Base product stock"}</option>{productVariants.map(v=><option key={String(v.id)} value={String(v.id)}>{String(v.name)} · {String(v.sku)}</option>)}</select></Field><Field label="Quantity change (+/-)"><input className="admin-field" type="number" step="1" required value={delta} onChange={e=>setDelta(e.target.value)} placeholder="e.g. 12 or -2"/></Field><Field label="Reason"><input className="admin-field" minLength={3} required value={reason} onChange={e=>setReason(e.target.value)} placeholder="Cycle count, damage, restock…"/></Field><Field label="Reference (optional)" full><input className="admin-field" value={reference} onChange={e=>setReference(e.target.value)} placeholder="Purchase order, audit, note"/></Field></div>{selectedProduct&&<p className="admin-muted">Selected product: {String(selectedProduct.name)}</p>}<ErrorLine error={error}/><button className="admin-button" disabled={busy||!productId} type="submit">{busy?"Recording…":"Record adjustment"}</button></form></aside></div><section style={{marginTop:27}}><h2 className="admin-section-title">Recent movements <small>LAST 100 DATABASE EVENTS</small></h2><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Time</th><th>Product</th><th>SKU</th><th>Change</th><th>Reason</th><th>Reference</th></tr></thead><tbody>{initial.movements.map(m=><tr key={String(m.id)}><td>{date(m.created_at)}</td><td>{String(m.product_name)}</td><td>{String(m.sku??"—")}</td><td className={Number(m.quantity_delta)>0?"admin-trend-up":"admin-trend-down"}>{Number(m.quantity_delta)>0?"+":""}{String(m.quantity_delta)}</td><td>{String(m.reason)}</td><td>{String(m.reference??"—")}</td></tr>)}</tbody></table>{!initial.movements.length&&<div className="admin-empty"><strong>No stock movements recorded</strong>Adjustments will appear here after the first change.</div>}</div></section></>;
}

export function OrdersTable({initial}:{initial:Row[]}){const [q,setQ]=useState("");const rows=initial.filter(row=>`${row.order_number} ${row.email}`.toLowerCase().includes(q.toLowerCase()));return <><Heading eyebrow="COMMERCE / ORDERS" title="Order book" detail={`${initial.length} recent orders · payment state is set by confirmed payment events`}/><div className="admin-toolbar"><label className="admin-field admin-search" style={{display:"flex",alignItems:"center",gap:8}}><Search size={14}/><input aria-label="Search orders" value={q} onChange={e=>setQ(e.target.value)} placeholder="Order number or email" style={{border:0,outline:0,background:"transparent",color:"inherit",width:"100%"}}/></label></div><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Payment</th><th>Fulfillment</th><th/></tr></thead><tbody>{rows.map(o=><tr key={String(o.id)}><td><b>{String(o.order_number??String(o.id).slice(0,8))}</b></td><td>{String(o.email??"Guest")}</td><td>{date(o.created_at)}</td><td>{money(Number(o.total_cents),String(o.currency??"USD").toUpperCase())}</td><td><Status value={o.payment_status}/></td><td><Status value={o.fulfillment_status}/></td><td><Link className="admin-button admin-button-quiet admin-button-small" href={`/admin/orders/${o.id}`}>Open <ChevronRight size={12}/></Link></td></tr>)}</tbody></table>{!rows.length&&<div className="admin-empty"><strong>No orders found</strong>Try a different order number or email address.</div>}</div></>;}

export function OrderDetail({initial}:{initial:{order:Row;items:Row[];payment:Row|null;events:Row[]}}){const router=useRouter();const o=initial.order;const [status,setStatus]=useState(String(o.fulfillment_status));const [carrier,setCarrier]=useState(String(o.shipment_carrier??""));const [tracking,setTracking]=useState(String(o.tracking_number??""));const [trackingUrl,setTrackingUrl]=useState(String(o.tracking_url??""));const [note,setNote]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{await requestJson(`/api/admin/orders/${o.id}`,{method:"PATCH",body:JSON.stringify({fulfillmentStatus:status,carrier,trackingNumber:tracking,trackingUrl,note})});notifyAdmin("Order fulfillment updated.");setNote("");router.refresh();}catch(x){setError(x instanceof Error?x.message:"Order update failed.");}finally{setBusy(false);}}
  return <><Heading eyebrow="COMMERCE / ORDER DETAIL" title={String(o.order_number??"Order")} detail={`Placed ${date(o.created_at)} · ${String(o.email??"Guest checkout")}`} action={<Link className="admin-button admin-button-quiet" href="/admin/orders">Back to orders</Link>}/><div className="admin-grid admin-overview-grid"><div className="admin-grid"><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Line items <small>{initial.items.length} LINES</small></h2>{initial.items.map(item=><div className="admin-list-row" key={String(item.id)}><div className="admin-list-main"><b>{String(item.product_name)}</b><span>{String(item.variant_id??"Standard")} · qty {String(item.quantity)}</span></div><div className="admin-list-value"><b>{money(Number(item.unit_amount_cents)*Number(item.quantity),String(o.currency??"USD").toUpperCase())}</b></div></div>)}<div className="admin-list-row"><div className="admin-list-main"><b>Order total</b></div><div className="admin-list-value"><b>{money(Number(o.total_cents),String(o.currency??"USD").toUpperCase())}</b></div></div></section><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Delivery address</h2><pre style={{whiteSpace:"pre-wrap",fontSize:10,color:"#aaa",lineHeight:1.8,fontFamily:"inherit"}}>{JSON.stringify(o.shipping_address??{},null,2)}</pre><p className="admin-muted">Shipping · {String(o.shipping_method??"Standard")} · {String(o.shipping_estimate??"Estimate unavailable")}</p></section><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Order timeline</h2>{initial.events.map(event=><div className="admin-list-row" key={String(event.id)}><div className="admin-list-main"><b>{String(event.event_type)}</b><span>{String(event.description)}</span></div><span className="admin-muted">{date(event.created_at)}</span></div>)}</section></div><aside className="admin-grid"><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Payment <Status value={o.payment_status}/></h2><p className="admin-muted">Payment state is updated by the verified payment provider event.</p>{initial.payment&&<div className="admin-list-row"><span className="admin-muted">Amount</span><b>{money(Number(initial.payment.amount_cents),String(initial.payment.currency??"USD").toUpperCase())}</b></div>}{Boolean(initial.payment?.stripe_payment_intent_id)&&<p className="admin-muted">Intent · {String(initial.payment?.stripe_payment_intent_id)}</p>}</section><form className="admin-panel admin-panel-pad" onSubmit={submit}><h2 className="admin-section-title">Fulfillment update</h2><div className="admin-form-grid"><Field label="Status" full><select className="admin-field admin-select" value={status} onChange={e=>setStatus(e.target.value)}>{["unfulfilled","processing","shipped","delivered","cancelled","returned"].map(v=><option key={v}>{v}</option>)}</select></Field><Field label="Carrier"><input className="admin-field" value={carrier} onChange={e=>setCarrier(e.target.value)}/></Field><Field label="Tracking number"><input className="admin-field" value={tracking} onChange={e=>setTracking(e.target.value)}/></Field><Field label="Tracking URL" full><input className="admin-field" type="url" value={trackingUrl} onChange={e=>setTrackingUrl(e.target.value)} placeholder="https://…"/></Field><Field label="Timeline note" full><input className="admin-field" minLength={3} value={note} onChange={e=>setNote(e.target.value)} required placeholder="Describe this fulfillment update"/></Field></div><ErrorLine error={error}/><button className="admin-button" disabled={busy} type="submit">{busy?"Updating…":"Save fulfillment"}</button></form></aside></div></>;}

export function CustomersTable({initial,page,lastPage,total}:{initial:Row[];page:number;lastPage:number;total:number}){const [q,setQ]=useState("");const rows=initial.filter(c=>`${c.email} ${(c.profile as Row|null)?.full_name??""}`.toLowerCase().includes(q.toLowerCase()));return <><Heading eyebrow="COMMERCE / CUSTOMERS" title="Customer index" detail="Authenticated customer records, order count and paid lifetime spend from Supabase."/><div className="admin-toolbar"><label className="admin-field admin-search" style={{display:"flex",alignItems:"center",gap:8}}><Search size={14}/><input aria-label="Search customers" value={q} onChange={e=>setQ(e.target.value)} placeholder="Name or email on this page" style={{border:0,outline:0,background:"transparent",color:"inherit",width:"100%"}}/></label><span className="admin-muted">{total.toLocaleString()} accounts · page {page} of {lastPage}</span></div><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Customer</th><th>Joined</th><th>Orders</th><th>Paid spend</th><th>Last sign in</th><th/></tr></thead><tbody>{rows.map(c=><tr key={String(c.id)}><td><div className="admin-list-main"><b>{String((c.profile as Row|null)?.full_name||c.email)}</b><span>{String(c.email)}</span></div></td><td>{date(c.createdAt)}</td><td>{String(c.count)}</td><td>{money(Number(c.spend))}</td><td>{date(c.lastSignInAt)}</td><td><Link className="admin-button admin-button-quiet admin-button-small" href={`/admin/customers/${c.id}`}>Profile <ChevronRight size={12}/></Link></td></tr>)}</tbody></table>{!rows.length&&<div className="admin-empty"><strong>No customer accounts found</strong>Guest orders remain visible in the order book.</div>}</div><div className="admin-actions" style={{justifyContent:"space-between",marginTop:14}}><span className="admin-muted">Showing {rows.length} of {total} accounts</span><div className="admin-actions"><Link aria-disabled={page<=1} className={`admin-button admin-button-quiet admin-button-small ${page<=1?"disabled":""}`} href={`/admin/customers?page=${Math.max(1,page-1)}`}>Previous</Link><Link aria-disabled={page>=lastPage} className={`admin-button admin-button-quiet admin-button-small ${page>=lastPage?"disabled":""}`} href={`/admin/customers?page=${Math.min(lastPage,page+1)}`}>Next</Link></div></div></>;}

export function CustomerDetail({initial}:{initial:{user:Row;profile:Row|null;orders:Row[];addresses:Row[]}}){const {user,profile,orders,addresses}=initial;const paid=orders.filter(o=>o.payment_status==="paid").reduce((s,o)=>s+Number(o.total_cents),0);return <><Heading eyebrow="COMMERCE / CUSTOMER" title={String(profile?.full_name||user.email)} detail={`Customer since ${date(user.created_at)} · ${String(user.email)}`} action={<Link href="/admin/customers" className="admin-button admin-button-quiet">Back to customers</Link>}/><div className="admin-grid admin-stat-grid"><Stat label="Lifetime spend" value={money(paid)}/><Stat label="Orders" value={String(orders.length)}/><Stat label="Last sign in" value={date(user.last_sign_in_at)}/><Stat label="Account state" value={user.banned_until?"Restricted":"Active"}/></div><div className="admin-grid admin-overview-grid"><section><h2 className="admin-section-title">Order history</h2><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Fulfillment</th></tr></thead><tbody>{orders.map(o=><tr key={String(o.id)}><td><Link href={`/admin/orders/${o.id}`}>{String(o.order_number??String(o.id).slice(0,8))}</Link></td><td>{date(o.created_at)}</td><td>{money(Number(o.total_cents),String(o.currency??"USD").toUpperCase())}</td><td><Status value={o.payment_status}/></td><td><Status value={o.fulfillment_status}/></td></tr>)}</tbody></table>{!orders.length&&<div className="admin-empty"><strong>No orders</strong>This customer has no recorded orders.</div>}</div></section><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Saved addresses <small>{addresses.length}</small></h2>{addresses.map(a=><div className="admin-list-row" key={String(a.id)}><div className="admin-list-main"><b>{String(a.recipient)}</b><span>{String(a.line1)}, {String(a.city)}, {String(a.region)} {String(a.postal_code)}, {String(a.country_code)}</span></div></div>)}{!addresses.length&&<p className="admin-muted">No saved address records.</p>}<hr style={{borderColor:"var(--admin-line)",margin:"18px 0"}}/><h2 className="admin-section-title">Contact preferences</h2><p className="admin-muted">Marketing · {profile?.email_marketing?"subscribed":"not subscribed"}</p><p className="admin-muted">Order updates · {profile?.order_updates?"enabled":"disabled"}</p></section></div></>;}

function Stat({label,value,note,icon}:{label:string;value:string;note?:string;icon?:React.ReactNode}){return <div className="admin-panel admin-stat"><div className="admin-stat-label">{label}{icon}</div><div className="admin-stat-value">{value}</div>{note&&<div className="admin-stat-note">{note}</div>}</div>;}

type Discount=Row&{id:string;code:string;discount_type:"percent"|"fixed";amount:number;minimum_subtotal_cents:number;maximum_discount_cents:number|null;usage_limit:number|null;usage_count:number;starts_at:string|null;expires_at:string|null;active:boolean};
function discountForm(v?:Discount){return {code:v?.code??"",discountType:v?.discount_type??"percent",amount:String(v?.amount??10),minimumSubtotal:String(Number(v?.minimum_subtotal_cents??0)/100),maximumDiscount:v?.maximum_discount_cents==null?"":String(v.maximum_discount_cents/100),usageLimit:v?.usage_limit==null?"":String(v.usage_limit),startsAt:v?.starts_at?new Date(v.starts_at).toISOString().slice(0,16):"",expiresAt:v?.expires_at?new Date(v.expires_at).toISOString().slice(0,16):"",active:v?.active??true};}
export function DiscountsManager({initial}:{initial:Discount[]}){const router=useRouter();const [editing,setEditing]=useState<Discount|undefined>();const [creating,setCreating]=useState(false);const [form,setForm]=useState(()=>discountForm());const [error,setError]=useState("");const [busy,setBusy]=useState(false);
 function start(v?:Discount){setEditing(v);setCreating(!v);setForm(discountForm(v));setError("");}
 async function save(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const payload={code:form.code,discountType:form.discountType,amount:Number(form.amount),minimumSubtotalCents:Math.round(Number(form.minimumSubtotal)*100),maximumDiscountCents:form.maximumDiscount?Math.round(Number(form.maximumDiscount)*100):null,usageLimit:form.usageLimit?Number(form.usageLimit):null,startsAt:form.startsAt?new Date(form.startsAt).toISOString():null,expiresAt:form.expiresAt?new Date(form.expiresAt).toISOString():null,active:form.active};await requestJson(editing?`/api/admin/discounts/${editing.id}`:"/api/admin/discounts",{method:editing?"PATCH":"POST",body:JSON.stringify(payload)});notifyAdmin(editing?"Discount updated.":"Discount created.");setEditing(undefined);setCreating(false);router.refresh();}catch(x){setError(x instanceof Error?x.message:"Discount could not be saved.");}finally{setBusy(false);}}
 async function remove(v:Discount){if(!window.confirm(`Delete discount ${v.code}?`))return;try{await requestJson(`/api/admin/discounts/${v.id}`,{method:"DELETE"});notifyAdmin("Discount deleted.");router.refresh();}catch(x){setError(x instanceof Error?x.message:"Discount could not be deleted.");}}
 return <><Heading eyebrow="COMMERCE / PROMOTIONS" title="Discounts" detail="Discount rules are read by checkout and applied against server-calculated totals." action={<button className="admin-button" onClick={()=>start()}><Plus size={14}/> New discount</button>}/><ErrorLine error={error}/><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Code</th><th>Rule</th><th>Minimum</th><th>Usage</th><th>Validity</th><th>Status</th><th/></tr></thead><tbody>{initial.map(v=><tr key={v.id}><td><b style={{letterSpacing:".1em"}}>{v.code}</b></td><td>{v.discount_type==="percent"?`${v.amount}%`:`${money(v.amount)}`} off</td><td>{money(v.minimum_subtotal_cents)}</td><td>{v.usage_count} / {v.usage_limit??"∞"}</td><td>{v.starts_at?date(v.starts_at):"Now"} – {v.expires_at?date(v.expires_at):"No expiry"}</td><td><Status value={v.active?"active":"inactive"}/></td><td><div className="admin-actions"><button className="admin-button admin-button-quiet admin-button-small" onClick={()=>start(v)}><Pencil size={11}/> Edit</button><button className="admin-button admin-button-danger admin-button-small" onClick={()=>remove(v)} aria-label={`Delete ${v.code}`}><Trash2 size={11}/></button></div></td></tr>)}</tbody></table>{!initial.length&&<div className="admin-empty"><strong>No discounts configured</strong>Create a code to make it available to checkout.</div>}</div>{(creating||editing)&&<Modal title={editing?`Edit ${editing.code}`:"Create discount"} onClose={()=>{setCreating(false);setEditing(undefined)}}><form onSubmit={save}><div className="admin-form-grid"><Field label="Code"><input className="admin-field" required value={form.code} onChange={e=>setForm({...form,code:e.target.value.toUpperCase()})}/></Field><Field label="Type"><select className="admin-field admin-select" value={form.discountType} onChange={e=>setForm({...form,discountType:e.target.value as "percent"|"fixed"})}><option value="percent">Percentage</option><option value="fixed">Fixed amount (cents)</option></select></Field><Field label={form.discountType==="percent"?"Percent off":"Amount off (cents)"}><input className="admin-field" type="number" min="1" max={form.discountType==="percent"?100:100000000} required value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></Field><Field label="Minimum subtotal (USD)"><input className="admin-field" type="number" min="0" step="0.01" value={form.minimumSubtotal} onChange={e=>setForm({...form,minimumSubtotal:e.target.value})}/></Field><Field label="Maximum discount (USD)"><input className="admin-field" type="number" min="0" step="0.01" value={form.maximumDiscount} onChange={e=>setForm({...form,maximumDiscount:e.target.value})}/></Field><Field label="Usage limit"><input className="admin-field" type="number" min="1" value={form.usageLimit} onChange={e=>setForm({...form,usageLimit:e.target.value})}/></Field><Field label="Starts at"><input className="admin-field" type="datetime-local" value={form.startsAt} onChange={e=>setForm({...form,startsAt:e.target.value})}/></Field><Field label="Expires at"><input className="admin-field" type="datetime-local" value={form.expiresAt} onChange={e=>setForm({...form,expiresAt:e.target.value})}/></Field><div className="admin-form-field full"><label className="admin-check"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/> Active in checkout</label></div></div><ErrorLine error={error}/><div className="admin-modal-foot"><button type="button" className="admin-button admin-button-quiet" onClick={()=>{setCreating(false);setEditing(undefined)}}>Cancel</button><button disabled={busy} className="admin-button">{busy?"Saving…":"Save discount"}</button></div></form></Modal>}</>;
}

const template=(kind:string)=>kind==="collections"?{slug:"new-collection",name:"New collection",eyebrow:"Collection study",description:"Collection description",statement:"Collection statement",imageUrl:"/images/concepts/object-concept.webp",imageAlt:"Collection image description",accentColor:"#bda27b",categories:["objects"],isFeatured:false,sortOrder:10,isPublished:false}:kind==="stories"?{slug:"new-story",title:"New story",eyebrow:"VANTA journal",category:"Design philosophy",dek:"Editorial introduction",heroImage:"/images/concepts/object-concept.webp",heroAlt:"Story image description",relatedProductSlug:null,author:"VANTA Studio",readTimeMinutes:4,body:[{type:"paragraph",text:"Story text"}],isFeatured:false,isPublished:false,sortOrder:10,publishedAt:new Date().toISOString()}:kind==="drops"?{slug:"new-drop",title:"New release",eyebrow:"Release signal",description:"Release details",productSlug:null,heroImage:"/images/concepts/object-concept.webp",heroAlt:"Drop image description",releaseAt:null,endsAt:null,notifyEnabled:true,isPublished:false,sortOrder:10}: {sectionKey:"new-section",title:"Homepage section",content:{description:"Section description"},enabled:true,sortOrder:10};
function contentForm(kind:string,row:Row){if(kind==="collections")return{slug:row.slug,name:row.name,eyebrow:row.eyebrow,description:row.description,statement:row.statement,imageUrl:row.image_url,imageAlt:row.image_alt,accentColor:row.accent_color,categories:row.categories,isFeatured:row.is_featured,sortOrder:row.sort_order,isPublished:row.is_published};if(kind==="stories")return{slug:row.slug,title:row.title,eyebrow:row.eyebrow,category:row.category,dek:row.dek,heroImage:row.hero_image,heroAlt:row.hero_alt,relatedProductSlug:row.related_product_slug,author:row.author,readTimeMinutes:row.read_time_minutes,body:row.body,isFeatured:row.is_featured,isPublished:row.is_published,sortOrder:row.sort_order,publishedAt:row.published_at};if(kind==="drops")return{slug:row.slug,title:row.title,eyebrow:row.eyebrow,description:row.description,productSlug:row.product_slug,heroImage:row.hero_image,heroAlt:row.hero_alt,releaseAt:row.release_at,endsAt:row.ends_at,notifyEnabled:row.notify_enabled,isPublished:row.is_published,sortOrder:row.sort_order};return{sectionKey:row.section_key,title:row.title,content:row.content,enabled:row.enabled,sortOrder:row.sort_order};}
const itemLabel=(kind:string,row:Row)=>String(row.name??row.title??row.section_key??row.slug);
export function ContentManager({kind,initial,products=[]}:{kind:"collections"|"stories"|"drops"|"homepage";initial:Row[];products?:FeaturedProduct[]}){const router=useRouter();const [editing,setEditing]=useState<Row|null>(null);const [json,setJson]=useState("");const [error,setError]=useState("");const [busy,setBusy]=useState(false);const featured=products.filter(p=>p.is_featured);const displayKind=kind==="homepage"?"homepage sections":kind;
 function open(row?:Row){setEditing(row??{});setJson(JSON.stringify(row?contentForm(kind,row):template(kind),null,2));setError("");}
 async function save(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const data=JSON.parse(json);const key=editing&&Object.keys(editing).length?(kind==="homepage"?String(editing.section_key):String(editing.slug)):undefined;await requestJson(`/api/admin/content/${kind}`,{method:key?"PATCH":"POST",body:JSON.stringify(key?{key,data}:{...data})});notifyAdmin(`${kind.slice(0,-1)} saved.`);setEditing(null);router.refresh();}catch(x){setError(x instanceof Error?x.message:"Content could not be saved. Check JSON syntax and required fields.");}finally{setBusy(false);}}
 async function remove(row:Row){const key=String(kind==="homepage"?row.section_key:row.slug);if(!window.confirm(`Delete ${itemLabel(kind,row)}?`))return;try{await requestJson(`/api/admin/content/${kind}?key=${encodeURIComponent(key)}`,{method:"DELETE"});notifyAdmin("Content deleted.");router.refresh();}catch(x){setError(x instanceof Error?x.message:"Delete failed.");}}
 async function toggle(p:FeaturedProduct){try{await requestJson("/api/admin/content/featured",{method:"PATCH",body:JSON.stringify({id:p.id,isFeatured:!p.is_featured,featuredRank:p.featured_rank||999})});router.refresh();}catch(x){setError(x instanceof Error?x.message:"Could not update featured products.");}}
 return <><Heading eyebrow={`STUDIO / ${displayKind.toUpperCase()}`} title={kind==="collections"?"Collection studio":"Editorial content"} detail={`Manage ${displayKind} records from Supabase. Dates remain empty until a release is confirmed.`} action={<button className="admin-button" onClick={()=>open()}><Plus size={14}/> New record</button>}/><ErrorLine error={error}/>{kind==="collections"&&<div className="admin-callout">Collection product membership is driven by product collection slugs. Edit product records to place them in this collection; featured state is managed below.</div>}{kind==="collections"&&<section style={{marginBottom:25}}><h2 className="admin-section-title">Featured products <small>{featured.length} SELECTED</small></h2><div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>Product</th><th>Collection</th><th>Rank</th><th>Featured</th></tr></thead><tbody>{products.map(p=><tr key={p.id}><td>{p.name}</td><td>{String(p.collection_name)}</td><td>{p.featured_rank}</td><td><button className="admin-icon-button" onClick={()=>toggle(p)} aria-label={`${p.is_featured?"Unfeature":"Feature"} ${p.name}`}><Star size={14} fill={p.is_featured?"#c3a77d":"none"}/></button></td></tr>)}</tbody></table></div></section>}<div className="admin-panel admin-table-wrap"><table className="admin-table"><thead><tr><th>{kind==="collections"?"Collection":kind==="stories"?"Story":kind==="drops"?"Drop":"Section"}</th><th>Updated / release</th><th>Visibility</th><th>Featured / notify</th><th/></tr></thead><tbody>{initial.map(row=><tr key={String(row.slug??row.section_key)}><td><div className="admin-list-main"><b>{itemLabel(kind,row)}</b><span>{String(row.slug??row.section_key)}</span></div></td><td>{date(row.updated_at??row.release_at??row.published_at)}</td><td><Status value={Boolean(row.is_published??row.enabled)?"published":"draft"}/></td><td>{kind==="drops"?Boolean(row.notify_enabled)?"Notify enabled":"Notify off":kind==="homepage"?"—":Boolean(row.is_featured)?"Featured":"Standard"}</td><td><div className="admin-actions"><button className="admin-button admin-button-quiet admin-button-small" onClick={()=>open(row)}><Pencil size={11}/> Edit</button><button className="admin-button admin-button-danger admin-button-small" onClick={()=>remove(row)} aria-label={`Delete ${itemLabel(kind,row)}`}><Trash2 size={11}/></button></div></td></tr>)}</tbody></table>{!initial.length&&<div className="admin-empty"><strong>No records yet</strong>Create the first {kind.slice(0,-1)} record.</div>}</div>{editing&&<Modal title={Object.keys(editing).length?`Edit ${itemLabel(kind,editing)}`:`New ${kind.slice(0,-1)}`} onClose={()=>setEditing(null)}><form onSubmit={save}><p className="admin-muted">Edit the validated record shape. Stored fields and timestamps stay in the database.</p><textarea className="admin-textarea" style={{minHeight:330,fontFamily:"var(--font-mono)",fontSize:10}} value={json} onChange={e=>setJson(e.target.value)} spellCheck={false}/><ErrorLine error={error}/><div className="admin-modal-foot"><button type="button" className="admin-button admin-button-quiet" onClick={()=>setEditing(null)}>Cancel</button><button className="admin-button" disabled={busy}>{busy?"Saving…":"Save record"}</button></div></form></Modal>}</>;
}

export function AnalyticsPage({data}:{data:Row}){
  const categories=(data.categorySales as Row[])??[];const sellers=(data.bestSellers as Row[])??[];const trend=(data.trend as Row[])??[];const inventory=(data.inventoryTrend as Row[])??[];
  const revenueMax=Math.max(1,...trend.map(t=>Number(t.revenueCents)));const orderMax=Math.max(1,...trend.map(t=>Number(t.orders)));const inventoryMax=Math.max(1,...inventory.flatMap(v=>[Number(v.received),Math.abs(Number(v.removed))]));const categoryMax=Math.max(1,...categories.map(v=>Number(v.revenueCents)));const sellerMax=Math.max(1,...sellers.map(v=>Number(v.units)));
  return <><Heading eyebrow="STUDIO / ANALYTICS" title="Signals & performance" detail="Metrics are calculated from paid orders, recorded stock movements and tracked sessions in the database."/>
    <div className="admin-grid admin-stat-grid"><Stat label="Paid revenue" value={money(Number(data.revenueCents))} note={`${data.paidOrders} paid orders`}/><Stat label="Average order value" value={money(Number(data.averageOrderValueCents))} note="Paid orders only"/><Stat label="Customer profiles" value={String(data.customers)} note="Supabase profiles"/><Stat label="Purchase conversion" value={data.conversion?`${(Number((data.conversion as Row).purchaseRate)*100).toFixed(1)}%`:"No tracked sessions"} note={data.conversion?`${String((data.conversion as Row).sessions)} page sessions / last 30 days`:"Event tracking has no page views"}/></div>
    <div className="admin-grid admin-overview-grid"><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Revenue trend <small>30 DAYS / PAID ORDERS</small></h2><div className="admin-chart" role="img" aria-label="Daily paid revenue over the last 30 days">{trend.map(entry=><div key={String(entry.date)} className="admin-chart-bar" title={`${date(entry.date)} · ${money(Number(entry.revenueCents))}`} style={{height:`${Math.max(2,Number(entry.revenueCents)/revenueMax*100)}%`,opacity:Number(entry.revenueCents)?0.9:0.2}}/>)}</div><div className="admin-chart-labels"><span>{date(trend[0]?.date)}</span><span>{date(trend.at(-1)?.date)}</span></div></section><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Paid order trend <small>30 DAYS / ORDERS</small></h2><div className="admin-chart" role="img" aria-label="Daily paid order volume over the last 30 days">{trend.map(entry=><div key={String(entry.date)} className="admin-chart-bar" title={`${date(entry.date)} · ${entry.orders} orders`} style={{height:`${Math.max(2,Number(entry.orders)/orderMax*100)}%`,background:"linear-gradient(0deg,#536448,#9bb28b)",opacity:Number(entry.orders)?0.9:0.2}}/>)}</div><div className="admin-chart-labels"><span>{date(trend[0]?.date)}</span><span>{date(trend.at(-1)?.date)}</span></div></section></div>
    <div className="admin-grid admin-overview-grid" style={{marginTop:14}}><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Category performance <small>PAID ITEM REVENUE</small></h2>{categories.map(cat=><div className="admin-performance-row" key={String(cat.category)}><div className="admin-performance-label"><b>{String(cat.category)}</b><span>{String(cat.units)} units · {money(Number(cat.revenueCents))}</span></div><div className="admin-performance-track"><span style={{width:`${Number(cat.revenueCents)/categoryMax*100}%`}}/></div></div>)}{!categories.length&&<p className="admin-muted">No paid item records yet.</p>}</section><section className="admin-panel admin-panel-pad"><h2 className="admin-section-title">Product performance <small>PAID UNITS SOLD</small></h2>{sellers.map((item,index)=><div className="admin-performance-row" key={String(item.slug)}><div className="admin-performance-label"><b>{String(item.name)}</b><span>{String(item.units)} units · {money(Number(item.revenueCents))}</span></div><div className="admin-performance-track"><span className={index===0?"gold":""} style={{width:`${Number(item.units)/sellerMax*100}%`}}/></div></div>)}{!sellers.length&&<p className="admin-muted">No paid item records yet.</p>}</section></div>
    <section className="admin-panel admin-panel-pad" style={{marginTop:14}}><h2 className="admin-section-title">Inventory movement <small>30 DAYS / RECORDED ADJUSTMENTS</small></h2><div role="img" aria-label="Daily stock received and removed from inventory" style={{height:145,display:"grid",gridTemplateColumns:"repeat(30,minmax(0,1fr))",gap:4,alignItems:"stretch",borderBottom:"1px solid var(--admin-line)"}}>{inventory.map(entry=><div key={String(entry.date)} title={`${date(entry.date)} · received ${entry.received} · removed ${Math.abs(Number(entry.removed))}`} style={{display:"grid",gridTemplateRows:"1fr 1fr",gap:1,minWidth:0}}><div style={{display:"flex",alignItems:"end",justifyContent:"center"}}><div style={{width:"72%",height:`${Math.max(Number(entry.received)?3:0,Number(entry.received)/inventoryMax*100)}%`,background:"#91ad7d",borderRadius:"2px 2px 0 0"}}/></div><div style={{display:"flex",alignItems:"start",justifyContent:"center",borderTop:"1px solid #44463f"}}><div style={{width:"72%",height:`${Math.max(Number(entry.removed)?3:0,Math.abs(Number(entry.removed))/inventoryMax*100)}%`,background:"#a96e60",borderRadius:"0 0 2px 2px"}}/></div></div>)}</div><div className="admin-chart-labels"><span>{date(inventory[0]?.date)}</span><span style={{color:"#91ad7d"}}>↑ Received</span><span style={{color:"#c98578"}}>↓ Removed</span><span>{date(inventory.at(-1)?.date)}</span></div></section>
  </>;
}

export function AdminNotice({message}:{message:string}){return <div className="admin-notice">{message}</div>;}

